WITH cleaned AS (SELECT id, device, browser, started_at, country, TRIM(browser) AS clean_browser, COALESCE(country, 'DIRECT') AS resolved_country FROM sessions WHERE started_at >= TO_DATE('2023-06-01') AND country IS NOT DISTINCT FROM 'UK'), flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT id, browser, started_at, country, clean_browser, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, browser, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, COUNT_IF(country = 'DE') AS de_events, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles FROM islands GROUP BY DATE_TRUNC('WEEK', started_at), browser ORDER BY week_start DESC;
